class BankAccount:
    def __init__(self, balance):
        self.__balance = balance

    def deposit(self, amount):
        if amount > 0:
            self.__balance += amount

    def get_balance(self):
        return self.__balance

account = BankAccount(1000)
account.deposit(500)
print(account.get_balance())

class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return '...'

class Cat(Animal):
    def speak(self):
        return f'{self.name} می‌گه میاو!'

class Dog(Animal):
    def speak(self):
        return f'{self.name} می‌گه وَف!'

for animal in [Cat('پیشی'), Dog('سگی')]:
    print(animal.speak())

class Shape:
    def area(self):
        pass

class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius
    def area(self):
        return 3.14 * self.radius ** 2

class Square(Shape):
    def __init__(self, side):
        self.side = side
    def area(self):
        return self.side ** 2

shapes = [Circle(5), Square(4)]
for s in shapes:
    print(s.area())

class Vector:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __add__(self, other):
        return Vector(self.x + other.x, self.y + other.y)

    def __repr__(self):
        return f'Vector({self.x}, {self.y})'

    def __len__(self):
        return int((self.x**2 + self.y**2)**0.5)

v1 = Vector(2, 3)
v2 = Vector(1, 1)
print(v1 + v2)
print(len(v1))

class Temperature:
    def __init__(self, celsius):
        self._celsius = celsius

    @property
    def fahrenheit(self):
        return self._celsius * 9/5 + 32

    @classmethod
    def from_fahrenheit(cls, f):
        return cls((f - 32) * 5/9)

    @staticmethod
    def is_freezing(c):
        return c <= 0

print(Temperature(100).fahrenheit)
print(Temperature.from_fahrenheit(212)._celsius)

class Employee:
    def __init__(self, name, salary):
        self.name = name
        self.salary = salary

    def bonus(self):
        return self.salary * 0.1

    def __str__(self):
        return f'{self.name}: {self.salary}'

class Manager(Employee):
    def bonus(self):
        return self.salary * 0.2

emp = Employee('علی', 1000000)
mgr = Manager('محمد', 2000000)
print(f'bonus علی: {emp.bonus()}')
print(f'bonus محمد: {mgr.bonus()}')

